    @DrawableRes
    fun resource(id: AppIconId, style: IconStyle, variant: IconVariant, selected: Boolean = false): Int {
        val choices = if (selected) active[id] ?: normal[id.ordinal] else normal[id.ordinal]
        return choices[style.ordinal * IconVariant.entries.size + variant.ordinal]
    }
